 */
public class StdDateFormat_setLenient_TriageGen1Test {

    private StdDateFormat dateFormat;

    @Before
    public void setUp() {
        dateFormat = new StdDateFormat();
    }





    @Test
    public void testSetLenient_NoChangeWhenAlreadyTrue() {
        dateFormat.setLenient(true);
        assertTrue(dateFormat.isLenient());

        // Call with same value to cover the case where _lenient == newValue
        // This ensures the branch is not entered and _clearFormats() is not called (implicitly)
        dateFormat.setLenient(true);
        assertTrue("State should remain true", dateFormat.isLenient());
    }




}

