package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.io.NumberInput;
import java.io.*;
import java.math.*;
import java.text.DateFormat;
import java.text.FieldPosition;
import java.text.ParseException;
import java.text.ParsePosition;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.Date;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for StdDateFormat.setLenient(boolean)
 */
public class StdDateFormat_setLenient_TriageGen1Test {

    private StdDateFormat dateFormat;

    @Before
    public void setUp() {
        dateFormat = new StdDateFormat();
    }









    @Test
    public void testSetLenient_FunctionalImpactOnParsing() throws ParseException {
        // This test verifies that changing leniency actually affects the behavior 
        // of the parse method, which is the side effect of _clearFormats() and setting the flag.

        // A date string that is invalid in strict mode but valid in lenient mode
        // Example: "2023-13-01" (Month 13 is invalid)
        String invalidDate = "2023-13-01";

        // Strict mode
        dateFormat.setLenient(false);
        try {
            dateFormat.parse(invalidDate);
            fail("Should have thrown ParseException in strict mode");
        } catch (ParseException e) {
            // Expected
        }

        // Lenient mode
        dateFormat.setLenient(true);
        Date parsedDate = dateFormat.parse(invalidDate);
        assertNotNull("Should have parsed date in lenient mode", parsedDate);
    }
}
